<?php $value=field_value($row,$key,$default??''); ?><div class="field <?= !empty($wide)?'full':'' ?>"><label for="<?= e($key) ?>"><?= e($label) ?> <?= !empty($required)?'<span aria-hidden="true">*</span>':'' ?></label><?php if(($kind??'text')==='editor'): ?><div class="editor" data-field="<?= e($key) ?>"><div class="editor-toolbar" role="toolbar" aria-label="<?= e($label) ?> formatting"><?php foreach(['bold'=>'Bold','italic'=>'Italic','underline'=>'Underline','insertUnorderedList'=>'Bullet list','insertOrderedList'=>'Numbered list','removeFormat'=>'Clear formatting'] as $command=>$text): ?><button class="btn btn-sm" type="button" data-command="<?= $command ?>" aria-label="<?= e($text) ?>" title="<?= e($text) ?>"><?= ['bold'=>'B','italic'=>'I','underline'=>'U','insertUnorderedList'=>'• List','insertOrderedList'=>'1. List','removeFormat'=>'Clear'][$command] ?></button><?php endforeach; ?></div><div class="editor-content prose" contenteditable="true" role="textbox" aria-multiline="true" aria-label="<?= e($label) ?>"><?= rich_text((string)$value) ?></div></div><textarea id="<?= e($key) ?>" name="<?= e($key) ?>" class="editor-source" rows="7"><?= e($value) ?></textarea><noscript>Enter plain text or basic HTML formatting in the text area above.</noscript><?php elseif(($kind??'text')==='textarea'): ?><textarea id="<?= e($key) ?>" name="<?= e($key) ?>" rows="4" <?= !empty($required)?'required':'' ?>><?= e($value) ?></textarea><?php else: ?><input id="<?= e($key) ?>" name="<?= e($key) ?>" type="<?= e($kind??'text') ?>" value="<?= e($value) ?>" <?= !empty($required)?'required':'' ?> <?= isset($max)?'maxlength="'.(int)$max.'"':'' ?>><?php endif; ?><?php if(!empty($help)): ?><small><?= e($help) ?></small><?php endif; ?></div>
